"""Three-way comparison: historical display, full original-method replay, correction."""
from pathlib import Path
import json,numpy as np,pandas as pd
HERE=Path(__file__).resolve().parent
results=[]
for slug in ['am-opus-r1-test-01','am-opus-r1-test-03']:
 original=HERE/'original-method-replays'/slug;corrected=HERE/'outputs'/slug
 checks=[]
 # These complete scientific input tables are regenerated by unchanged upstream cells.
 a=pd.read_csv(original/'assay_level_scores.csv',float_precision='round_trip')
 b=pd.read_csv(corrected/'assay_level_scores.csv',float_precision='round_trip')
 pd.testing.assert_frame_equal(a,b,check_exact=True)
 checks.append({'table':'assay_level_scores.csv','exact_dataframe_equal':True,'rows':len(a)})
 for name in ['input_processing_counts.csv','released_score_position_mapping.csv']:
  a=pd.read_csv(original/name,float_precision='round_trip');b=pd.read_csv(corrected/name,float_precision='round_trip')
  pd.testing.assert_frame_equal(a,b,check_exact=True)
  checks.append({'table':name,'exact_dataframe_equal':True,'rows':len(a)})
 for filename,keys in [('curves.csv',['scheme','method','level']),('paired_effects.csv',['subset','scheme','comparison'])]:
  old=pd.read_csv(original/filename,float_precision='round_trip');new=pd.read_csv(corrected/filename,float_precision='round_trip')
  joined=old.merge(new,on=keys,suffixes=('_original_replay','_correction'),validate='one_to_one')
  assert len(joined)==len(old)==len(new)
  difference=np.max(np.abs(joined.mean_original_replay-joined.mean_correction))
  assert difference<=2e-15,(slug,filename,difference)
  assert joined.n_assays_original_replay.equals(joined.n_assays_correction)
  previous=pd.read_csv(HERE/'before'/slug/('displayed-'+filename),float_precision='round_trip')
  three=previous.merge(joined,on=keys,validate='one_to_one').rename(columns={'mean':'mean_historical_display'})
  three.to_csv(original/('three-way-'+filename),index=False)
  checks.append({'table':filename,'rows':len(joined),'max_mean_difference_original_replay_to_correction':float(difference),'identical_assay_counts':True,'historical_comparison':'historical displayed precision only; no full original Nov9 assay outputs available'})
 results.append({'analysis_id':slug.replace('-test-','/test-'),'unmodified_original_full_replay':True,'same_pinned_public_inputs_and_current_environment':True,'checks':checks})
(HERE/'three-way-verification.json').write_text(json.dumps({'scope':'The protein-dependence correction leaves current reconstructed point estimates and assay eligibility unchanged. Historical display differences also appear in the unmodified full replay; their exact original-platform cause is not identified.','analyses':results},indent=2)+'\n')
print(json.dumps(results,indent=2))
